def concatenatedBinary(n: int) -> int:
    MOD = 10**9 + 7
    ans = 0
    length = 0
    for i in range(1, n + 1):
        # Check if i is a power of 2
        if (i & (i - 1)) == 0:
            length += 1
        ans = ((ans << length) | i) % MOD
    return ans

